import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CZDxhhIO.js";const u=JSON.parse('{"title":"The x402 facilitator","description":"What the facilitator does, why it is non-custodial, the scheme it implements, and where your API key fits.","frontmatter":{"description":"What the facilitator does, why it is non-custodial, the scheme it implements, and where your API key fits."},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(s,e,c,h,d,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="the-x402-facilitator" tabindex="-1">The x402 facilitator <a class="header-anchor" href="#the-x402-facilitator" aria-label="Permalink to &quot;The x402 facilitator&quot;">​</a></h1><p><code>x402</code> makes an ordinary HTTP request payable: a client that calls a paid endpoint gets back <code>402 Payment Required</code>, signs a payment, and retries with it. The <strong>facilitator</strong> is the HTTP service that turns that signed payment into a real, settled payment on the Canton Network — so your server never has to speak to a ledger, hold a wallet, or run a node. Your server (the resource server) just hands each payment to the facilitator, which does exactly two things with it: <code>POST /v2/verify</code> checks a signed payment against your terms without submitting or reserving anything; <code>POST /v2/settle</code> then executes it on Canton and returns the update id.</p><h2 id="non-custodial-by-construction" tabindex="-1">Non-custodial by construction <a class="header-anchor" href="#non-custodial-by-construction" aria-label="Permalink to &quot;Non-custodial by construction&quot;">​</a></h2><p>Canton settles in three steps — <code>prepare</code>, <code>sign</code>, <code>execute</code> — and that split is what makes the facilitator non-custodial. The payer does <code>prepare</code> and <code>sign</code> with its own key, without going through the facilitator. The facilitator only ever performs the final <code>execute</code> of a transaction the payer already signed: it never sees a private key, and it cannot move funds without that signature.</p><h2 id="the-payment-scheme" tabindex="-1">The payment scheme <a class="header-anchor" href="#the-payment-scheme" aria-label="Permalink to &quot;The payment scheme&quot;">​</a></h2><ul><li><code>exact-canton</code> — the payer transfers Canton Coin (Amulet) directly to your party; you receive CC.</li></ul><p><a href="/canton-x402-sdk/pr-73/api-reference.html#get-v2-supported"><code>GET /v2/supported</code></a> is the authority on what a given facilitator accepts — the network id and the asset to pay in.</p><h2 id="how-you-get-paid" tabindex="-1">How you get paid <a class="header-anchor" href="#how-you-get-paid" aria-label="Permalink to &quot;How you get paid&quot;">​</a></h2><p>Settlements land directly at your <strong>Canton party</strong> — the payout party of the project your API key belongs to. The payer transfers Amulet (CC) straight to it; the facilitator holds no balance, so there is nothing to withdraw. That relies on your payout party having a <code>TransferPreapproval</code>: to a party without one, Amulet delivers each payment as a transfer offer that the party has to accept before the CC is its own (see <a href="/canton-x402-sdk/pr-73/facilitator.html#what-settlement-does">What settlement does</a>). Completed settlements show up on the Settlements page of the merchant dashboard.</p><h2 id="your-api-key-is-the-facilitator-credential" tabindex="-1">Your API key is the facilitator credential <a class="header-anchor" href="#your-api-key-is-the-facilitator-credential" aria-label="Permalink to &quot;Your API key is the facilitator credential&quot;">​</a></h2><p>A key you create on the API keys page of the merchant dashboard is what your server sends as <code>Authorization: Bearer</code> to <code>/v2/verify</code> and <code>/v2/settle</code>. You can create and rotate keys in the dashboard yourself — no facilitator redeploy — and the key itself is never stored: what is kept is its hash, plus its <code>sk_live_</code>/<code>sk_test_</code> prefix and last four characters so you can tell your keys apart. A revocation can take up to a couple of minutes to take effect.</p><div class="tip custom-block"><p class="custom-block-title">Next</p><p><a href="/canton-x402-sdk/pr-73/getting-started.html">Getting started</a> takes you from a fresh account to a paid endpoint.</p></div>',12)])])}const y=t(i,[["render",n]]);export{u as __pageData,y as default};
